600	 */
601	/**
602	 * Valid hook names that can be used to filter which hooks an extension runs for.
603	 * If an extension specifies one of these as its function name (e.g., file://path:beforeAll),
604	 * it will only run for that specific hook and use the NEW calling convention: (context, { hookName }).
605	 * If an extension specifies a custom function name (e.g., file://path:myHandler),
606	 * it will run for ALL hooks and use the LEGACY calling convention: (hookName, context).
607	 */
608	const EXTENSION_HOOK_NAMES = new Set(['beforeAll', 'beforeEach', 'afterEach', 'afterAll']);
